 if(!s.lastInventory||now-s.lastInventory>=60000){s.lastInventory=now;for(const cmd of ['sub client all','sub slice all','sub tx all','sub pan all','meter list'])read(cmd);}
 if(!s.lastTxSub||now-s.lastTxSub>=5000){s.lastTxSub=now;read('sub tx all');read('sub radio all');}report();
}
flow.set('agctWritePermit',s.pending&&(s.pending.purpose==='restore'||scanning()&&s.auto)&&s.rx==='RX'&&now-s.rxAt<=C.rxFreshMs&&(s.pending.purpose==='restore'||freshMeters()&&atQuiet()&&!s.settingsError)?{
 command:s.pending.command,token:s.pending.token,epoch:s.epoch,expires:Math.min(now+1000,s.pending.at+C.ackTimeoutMs)}:null);
context.set('watcher',s);
node.status({fill:s.state==='ERROR'?'red':s.state==='DONE'?'green':s.auto?'blue':'grey',shape:'dot',text:s.state+': '+s.reason});
return [out.length?out:null,commands.length?commands:null,saves.length?saves:null];

if(msg.action || typeof msg.payload!=='string'){node.error('Blocked invalid command',msg);return null;}
if(/^(meter list|sub (client|slice|tx|pan|radio) all|sub meter \d+)$/.test(msg.payload))return {payload:msg.payload,_agctReadEpoch:msg._agctReadEpoch};
const match=msg.payload.match(/^slice s (\d+) agc_threshold=(\d{1,3})$/);
const permit=flow.get('agctWritePermit'),tag=msg._agctWrite;
const key=tag?tag.epoch+':'+tag.token:null;
if(match && Number(match[2])<=100 && permit && tag && permit.command===msg.payload && permit.token===tag.token && permit.epoch===tag.epoch && Date.now()<=permit.expires && context.get('lastSent')!==key){
 context.set('lastSent',key);flow.set('agctWritePermit',null);
 return {payload:msg.payload,_agctWrite:tag};
}
node.error('Blocked AGC-T write: no current RX/scan permit',msg);return null;

const h=msg.req?.headers||{},body=msg.payload,action=body?.action;
const originOK=typeof h.host==='string'&&['http://'+h.host,'https://'+h.host].includes(h.origin);
msg.headers={'Content-Type':'application/json','Cache-Control':'no-store'};
function reject(code,error){msg.statusCode=code;msg.payload={error};return [null,msg];}
if(!originOK||h['x-agct-watcher']!=='1'||!/^application\/json(?:;|$)/i.test(h['content-type']||'')||!['on','off','calibrate','settings','start','start100'].includes(action))return reject(400,'Ungültige Watcher-Anforderung');
const status=flow.get('agctUiStatus');
if(action!=='off'&&(!status||Date.now()-status.at>5000))return reject(409,'Keine aktuellen Watcher-Daten');
const running=['BAND_CHANGE','WAIT_RX','MEASURE_NOISE','SCAN_AGCT','KNEE_FOUND','APPLY'].includes(status?.state);
let command;
if(action==='settings'){
 if(running)return reject(409,'Zuerst Auto AUS wählen');
 const v = body.settings ?? { band: body.band, quietMHz: body.quietMHz, scanStart: body.scanStart };
 if(!v||typeof v.band!=='string'||!/^[A-Za-z0-9_-]{1,16}$/.test(v.band)||['__proto__','constructor'].includes(v.band)||
 !(v.quietMHz===null||(typeof v.quietMHz==='number'&&Number.isFinite(v.quietMHz)&&v.quietMHz>0&&v.quietMHz<=100000))||
 !(v.scanStart===null||(Number.isInteger(v.scanStart)&&v.scanStart>=0&&v.scanStart<=100)))return reject(400,'Band, Frequenz oder AGC-T-Startwert ungültig');
 if(v.band!==status.band && !Object.hasOwn(status.settings?.quietMHzByBand||{},v.band))return reject(400,'Unbekanntes Band');
 command={topic:'control/settings',payload:{band:v.band,quietMHz:v.quietMHz,scanStart:v.scanStart}};
}else if((action==='start'||action==='start100')){
 const quiet=status.settings?.quietMHzByBand?.[status.band];
 const freshMeters=['LEVEL','AGC+'].every(name=>{const m=status.meters?.[name];return m&&m.unit==='dBm'&&Number.isFinite(m.value)&&Date.now()-m.at<=3000;});
 const missing=[];
 if(running)missing.push('Messung läuft bereits');
 if(status.rxTx!=='RX')missing.push('Radio muss in RX sein');
 if(status.activeSlice==null)missing.push('kein aktiver Slice');
 if(status.band==null)missing.push('Band unbekannt');
 if(!status.settingsLoaded||status.settingsError)missing.push(status.settingsError||'Einstellungen werden geladen');
 if(typeof quiet!=='number')missing.push('Mess-QRG übernehmen');
 else if(typeof status.frequencyMHz!=='number'||Math.abs(quiet-status.frequencyMHz)>0.000001)missing.push('auf Mess-QRG '+quiet.toFixed(6)+' MHz abstimmen');
 if(!['slow','med','fast'].includes(status.agcMode))missing.push('AGC-Modus einschalten');
 if(!freshMeters)for(const name of ['LEVEL','AGC+']){
  const m=status.meters?.[name],label=name==='AGC+'?(status.agcMeterName||name):name;
  if(!m||m.unit!=='dBm'||!Number.isFinite(m.value)||Date.now()-m.at>3000)missing.push(label+'-Meter fehlt oder ist veraltet');
 }
 if(missing.length)return reject(409,'Start blockiert: '+missing.join('; '));
 command={topic:'control/start'};
}else if(action==='calibrate'){
 if(running||!status.auto||status.rxTx!=='RX'||status.activeSlice==null||status.band==null||!status.settingsLoaded||status.settingsError)return reject(409,'Kalibrierung aktuell nicht möglich');
 command={topic:'control/calibrate'};
}else command={topic:'control/auto',payload:action==='on'};
msg.statusCode=202;msg.payload={accepted:action};return [command,msg];

// Built-in fs only. Fixed path; no filenames or executable data accepted from the UI.
const path='/mnt/dietpi_userdata/node-red/agct-watcher-settings.json';
try {
 if(msg.topic==='settings/read'){
  const text=await fs.promises.readFile(path,'utf8');
  if(text.length>8192)throw Error('Settings file too large');
  return {topic:'settings/load',payload:text};
 }
 if(msg.topic==='settings/saved' && typeof msg.payload==='string' && msg.payload.length<=8192){
  JSON.parse(msg.payload);
  await fs.promises.writeFile(path+'.tmp',msg.payload+'\n',{encoding:'utf8',mode:0o600});
  await fs.promises.rename(path+'.tmp',path);
  return {topic:'settings/saved',_settingsToken:msg._settingsToken};
 }
 throw Error('Invalid settings storage request');
}catch(e){
 if(msg.topic==='settings/read' && e.code==='ENOENT')return {topic:'settings/missing'};
 node.warn('Watcher settings: '+e.message);
 return {topic:'settings/error',payload:e.message};
}
